occurrences.command:
python3 -I -c "
import json,sys
try:
    import jsonschema
except ImportError:
    jsonschema=None
for d,s in [('plan.json','plan.schema.json'),('answers.json','answers.schema.json'),('requests.json','requests.schema.json')]:
    doc=json.load(open(d)); sch=json.load(open(s))
    if jsonschema: jsonschema.validate(doc,sch); print(d,'valid')
    else: print(d,'parsed (no jsonschema)')
"
